<?php require_once __DIR__.'/../config.php'; require_role('parent');$s=$conn->prepare('SELECT p.first_name,p.last_name,s.first_name sf,s.last_name sl,c.class_name FROM parents p JOIN parent_students ps ON ps.parent_id=p.id JOIN students s ON s.id=ps.student_id JOIN classes c ON c.id=s.class_id WHERE p.user_id=?');$s->bind_param('i',$_SESSION['user_id']);$s->execute();$rows=$s->get_result();include '../includes/layout-start.php';?><h1>Parent dashboard</h1><div class="card"><table><tr><th>Child</th><th>Class</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=e($r['sf'].' '.$r['sl'])?></td><td><?=e($r['class_name'])?></td></tr><?php endwhile;?></table></div><?php include '../includes/layout-end.php';?>